Looking at this problem, I need to track reachable banana counts through n operations and find the earliest time-step for each count.

Key insights:
1. Operations work in order (type 1 = add, type 2 = multiply)
2. Each operation can be applied 0 to y_i times
3. Need to track which banana counts become reachable at each step
4. Use ceiling division carefully with x'_i / 10^5

```python
import math

def solution(input_str):
    lines = input_str.strip().split('\n')

    n_str = lines[0].strip()
    if not n_str:
        return ''
    n, m = map(int, n_str.split())

    ops = []
    for i in range(1, n + 1):
        if i < len(lines):
            parts = lines[i].strip().split()
            if len(parts) >= 3:
                t = int(parts[0])
                xi_prime = int(parts[1])
                yi = int(parts[2])
                ops.append((t, xi_prime, yi))

    first_seen = [-1] * (m + 1)
    first_seen[0] = 0

    reachable = {0}

    for step in range(1, n + 1):
        t, xi_prime, yi = ops[step - 1]

        denom = 100000

        new_reachable = set()
        current_reachable = reachable.copy()

        # Compute ceil(xi) using integer arithmetic
        # ceil(xi) = ceil(xi_prime / denom) = (xi_prime + denom - 1) // denom
        ceil_x = (xi_prime + denom - 1) // denom

        if t == 1:  # Type 1: k := ceil(k + xi)
            # ceil(k + xi) = k + ceil(xi) since k starts as integer
            x_add = ceil_x
            for k in current_reachable:
                # Generate all reachable values from k by applying 1 to yi times
                new_k = 0
                reached = 0
                while reached <= yi and new_k <= m:
                    if k == 0:
                        # First step from 0
                        if new_k == 0:
                            new_k = 1 if x_add > 0 else 0
                        else:
                            new_k = k + x_add * new_k
                    else:
                        new_k = k + x_add * new_k
                    if 0 < new_k <= m:
                        new_reachable.add(new_k)
                        first_seen[new_k] = min(first_seen[new_k], step) if new_k != 0 else 0
                    else:
                        new_k = m
                    reached += 1

        elif t == 2:  # Type 2: k := ceil(k * xi)
            target = set()
            for k in current_reachable:
                if k == 0:
                    new_k = 0
                else:
                    # Generate by multiplication
                    cur = k
                    for a in range(yi + 1):
                        if cur == 0:
                            new_k = 0
                        else:
                            new_k = (cur * xi_prime + denom - 1) // denom
                        if 0 < new_k <= m:
                            target.add(new_k)
                            first_seen[new_k] = min(first_seen[new_k], step) if new_k != 0 else 0
                        cur = new_k
            new_reachable = target

        reachable = new_reachable

    results = [str(first_seen[i]) for i in range(1, m + 1)]
    return '\n' + ' '.join(results) + '\n'
