sys.setrecursionlimit(200000)

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    k = math.ceil(n**0.5)

    adjacency = [[] for _ in range(n + 1)]

    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        adjacency[u].append(v)
        adjacency[v].append(u)

    visited = [False] * (n + 1)
    depth = [0] * (n + 1)
    parent = [0] * (n + 1)
    found_cycle = [False]
    cycle_result = []

    def dfs_for_cycle(u, p, d):
        if found_cycle[0]:
            return

        visited[u] = True
        depth[u] = d
        parent[u] = p

        for v in sorted(adjacency[u]):
            if v == p:
                continue

            if visited[v]:
                if v != p and depth[v] < depth[u]:
                    cycle_len = depth[u] - depth[v] + 1
                    if cycle_len >= k:
                        path = []
                        cur = u
                        while cur != v:
                            path.append(cur)
                            cur = parent[cur]
                        path.append(v)
                        cycle_result = path
                        found_cycle[0] = True
                        return
            else:
                dfs_for_cycle(v, u, d + 1)
                if found_cycle[0]:
                    return

    # Try DFS from all nodes to ensure connected graph traversal
    for start in range(1, n + 1):
        if not visited[start]:
            dfs_for_cycle(start, 0, 0)
        if found_cycle[0]:
            break

    if found_cycle[0]:
        return f"2\n{len(cycle_result)}\n{' '.join(map(str, cycle_result))}\n"

    # Find independent set
    independent = [False] * (n + 1)
    counter = 0

    def dfs_for_is(u, p, d):
        nonlocal counter
        if counter >= k:
            return

        if parent[u] == 0 or not independent[parent[u]]:
            independent[u] = True
            counter += 1

        for v in sorted(adjacency[u]):
            if v == p or parent[u] == 0:
                continue
            if not independent[v]:
                dfs_for_is(v, u, d + 1)
                if counter >= k:
                    return

    dfs_for_is(1, 0, 0)

    result_is = []
    for i in range(1, n + 1):
        if independent[i]:
            result_is.append(i)

    # If we didn't get enough vertices, try greedy from max degree or any unselected vertex
    while len(result_is) < k:
        for i in range(1, n + 1):
            if not independent[i] and not any(i in adj for adj in result_is if adj):
                independent[i] = True
                result_is.append(i)
                break

    return f"1\n{' '.join(map(str, result_is))}\n"
