import itertools

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "0"

    n, m = map(int, lines[0].split())

    # Parse the grid
    grid_lines = []
    for i in range(1, n + 1):
        if i < len(lines):
            grid_lines.append(lines[i])
        else:
            grid_lines.append('0' * m)

    # Collect all fixed cells (pre-colored vertices)
    fixed = []
    for i in range(n):
        if i < len(lines) - 1:
            row = lines[i + 1]
        else:
            row = '0' * m
        for j in range(m):
            c = row[j] if j < len(row) else '0'
            if c != '0':
                fixed.append((i, j, int(c)))

    # Try all 4! permutations of colors for the pattern
    # Pattern: color at (i,j) uses color from permutation[(i%2)*2 + (j%2)]
    # This creates a 4-coloring where no adjacent/diagonal cells have same color
    for perm in itertools.permutations([1, 2, 3, 4]):
        # perm[pattern_idx] assigns a color to each of the 4 pattern positions
        # Pattern positions: (0,0)->0, (0,1)->1, (1,0)->2, (1,1)->3

        # Check if this permutation is consistent with all fixed cells
        valid = True
        for i, j, c in fixed:
            pattern_idx = (i % 2) * 2 + (j % 2)
            if perm[pattern_idx] != c:
                valid = False
                break

        if valid:
            # Build the result grid with this valid permutation
            result = []
            for i in range(n):
                row_chars = []
                for j in range(m):
                    pattern_idx = (i % 2) * 2 + (j % 2)
                    row_chars.append(str(perm[pattern_idx]))
                result.append("".join(row_chars))
            return "\n".join(result)

    # No valid permutation found
    return "0"
