    # dp[i][balance + offset] = True if reachable
    offset = n
    dp = [[False] * (2*n + 1) for _ in range(n + 1)]
    parent = [[None] * (2*n + 1) for _ in range(n + 1)]

    dp[0][offset] = True
    parent[0][offset] = None

    for i in range(n):
        for balance in range(-i, i + 1):
            if not dp[i][balance + offset]:
                continue

            allowed = ['W', 'L', 'D'] if s[i] == '?' else [s[i]]

            for char in allowed:
                if char == 'W':
                    new_balance = balance + 1
                elif char == 'L':
                    new_balance = balance - 1
                else:
                    new_balance = balance

                if i + 1 < n:
                    # Intermediate: must stay within (-k, k)
                    if abs(new_balance) >= k:
                        continue

                if i + 1 == n:
                    # Final: must be exactly k
                    if abs(new_balance) != k:
                        continue

                if not dp[i + 1][new_balance + offset]:
                    dp[i + 1][new_balance + offset] = True
                    parent[i + 1][new_balance + offset] = (char, balance)

    # Reconstruct result from any valid endpoint
    result = []
    for balance in [-k, k]:
        if abs(balance) == k and dp[n][balance + offset]:
            curr = balance
            for i in range(n, 0, -1):
                char, prev = parent[i][curr + offset]
                result.append(char)
                curr = prev

            result.reverse()
            return ''.join(result) + '\n'

    return 'NO\n'
