                prefix_sum[i+1] = float('inf')
                continue
            prefix_sum[i+1] = prefix_sum[i] + cost[i]

        # Initialize answer with "no removal" case
        if prefix_sum[n] <= n * b:
            best_ans = min(best_ans, prefix_sum[n])

        # Try removing [i, j) where we keep prefix [0, i) and suffix [j, n)
        for j in range(n):
            # Skip invalid positions at start of suffix
            if cost[j] > b:
                continue

            # Find max valid starting position for prefix
            for i in range(j):
                if cost[i] > b:
                    break
                # Elements [i+1, j-1] are removed, elements [0, i] and [j, n-1] kept
                if i == 0:
                    prefix_cost = 0
                else:
