        ans = [''] * n
        stack = []

        for i in range(n):
            # Check if current lantern can illuminate waiting lanterns
            while stack and p[i] >= i - stack[-1]:
                stack.pop()

            if not stack:
                ans[i] = 'L'
            else:
                ans[i] = 'R'
                stack.append(i)

        def check(n, ans, p):
            for i in range(n):
                lit = False
                for j in range(i):
                    if ans[j] == 'R' and p[j] >= i - j:
                        lit = True
                        break
                if not lit:
                    for j in range(i + 1, n):
                        if ans[j] == 'L' and p[j] >= j - i:
                            lit = True
                if not lit:
                    return False
            return True

        if check(n, ans, p):
            results.append("YES")
            results.append("".join(ans))
        else:
            results.append("NO")

    return "\n".join(results) + "\n"
